function flattenObject(obj) {
  var result = {};
  var stack = [];

  if (obj === null || typeof obj !== "object" || Array.isArray(obj)) {
    return result;
  }

  stack.push({ value: obj, path: "" });

  while (stack.length) {
    var current = stack.pop();
    var key;

    for (key in current.value) {
      if (
        Object.prototype.hasOwnProperty.call(current.value, key) &&
        Object.prototype.propertyIsEnumerable.call(current.value, key)
      ) {
        var value = current.value[key];
        var path = current.path ? current.path + "." + key : key;
        var prototype = value !== null && typeof value === "object"
          ? Object.getPrototypeOf(value)
          : undefined;

        if (
          value !== null &&
          typeof value === "object" &&
          !Array.isArray(value) &&
          (prototype === Object.prototype || prototype === null)
        ) {
          stack.push({ value: value, path: path });
        } else {
          result[path] = value;
        }
      }
    }
  }

  return result;
}
